delete from public.features
where slug in ('caramel-founder-story', 'first-100-users');

update public.features
set status = 'draft', is_indexable = false, updated_at = timezone('utc', now())
where slug in ('grain-launch-story', 'flow-small-team', 'mood-taste-map', 'student-founder-week');

with posts (slug, title, excerpt, body, seo_title, seo_description, primary_keyword, secondary_keywords, published_at) as (
  values
  ('startup-promotion-guide', '스타트업 홍보, 처음이라면 무엇부터 해야 할까', '광고비보다 먼저 정리해야 할 스타트업 홍보의 기본 구조를 소개합니다.', $$[{"type":"text","heading":"홍보는 채널보다 메시지에서 시작합니다","body":"스타트업 홍보를 시작할 때 SNS 계정이나 보도자료부터 만들기 쉽습니다. 하지만 먼저 정리할 것은 ‘누구의 어떤 문제를 해결하는가’입니다. 한 문장으로 설명할 수 있어야 홈페이지, 소개글, 세일즈 대화의 방향이 흔들리지 않습니다."},{"type":"features","heading":"처음 2주에 할 일","items":[{"title":"핵심 고객 한 명 정하기","body":"모든 사람 대신 가장 먼저 반응할 한 사람의 상황을 구체적으로 적습니다."},{"title":"문제와 변화를 한 문장으로 쓰기","body":"기능이 아니라 사용자의 하루가 어떻게 달라지는지 설명합니다."},{"title":"반응을 기록하기","body":"조회수보다 질문, 저장, 답장처럼 실제 관심의 신호를 모읍니다."}]},{"type":"text","heading":"작은 홍보를 반복하세요","body":"초기 홍보의 목적은 크게 알리는 것이 아니라 메시지를 검증하는 것입니다. 고객이 이해한 언어를 다음 소개글에 반영하면, 홍보는 시간이 갈수록 더 선명해집니다."}]$$::jsonb, '스타트업 홍보 방법: 처음부터 고객에게 알리는 3단계', '광고비를 쓰기 전 스타트업이 정리해야 할 고객, 메시지, 반응 기록 방법을 안내합니다.', '스타트업 홍보', array['브랜드 홍보','초기 스타트업 마케팅'], now() - interval '1 day'),
  ('product-launch-checklist', '신제품 출시 전 체크리스트: 고객이 이해하는 출시를 만드는 법', '출시일 전에 제품, 메시지, 고객 접점을 점검하는 실전 체크리스트입니다.', $$[{"type":"text","heading":"출시는 기능 공개가 아니라 약속의 시작입니다","body":"신제품 출시일에는 팀이 만든 것을 보여 주지만, 고객은 자신의 문제를 해결할 수 있는지를 봅니다. 그래서 출시 준비는 기능 목록보다 고객이 처음 마주할 문장과 화면을 점검하는 일에서 시작해야 합니다."},{"type":"features","heading":"출시 전 필수 점검","items":[{"title":"첫 화면","body":"3초 안에 누구를 위한 제품인지, 무엇이 달라지는지 보여 줍니다."},{"title":"시작 경험","body":"가입 뒤 첫 행동까지의 단계를 줄이고 막히는 지점을 직접 확인합니다."},{"title":"문의 경로","body":"고객이 질문하거나 피드백을 남길 위치를 분명하게 둡니다."}]},{"type":"text","heading":"출시 다음 날이 더 중요합니다","body":"출시는 끝이 아니라 관찰의 시작입니다. 고객의 질문과 이탈 지점을 기록해 다음 업데이트의 우선순위를 정하세요."}]$$::jsonb, '신제품 출시 체크리스트: 고객이 이해하는 출시 준비', '신제품 출시 전 점검해야 할 메시지, 첫 사용 경험, 고객 피드백 경로를 정리했습니다.', '신제품 출시', array['제품 출시 전략','서비스 런칭'], now() - interval '2 days'),
  ('brand-story-writing', '브랜드 스토리 작성법: 우리 이야기를 고객의 언어로 바꾸는 법', '브랜드의 시작과 미션을 고객이 공감하는 이야기로 정리하는 방법입니다.', $$[{"type":"text","heading":"브랜드 스토리는 연혁이 아닙니다","body":"언제 회사를 만들었는지보다 중요한 것은 왜 이 문제가 계속 남아 있었는지입니다. 좋은 브랜드 스토리는 창업자의 이력만 나열하지 않고, 고객이 겪는 장면과 브랜드가 선택한 해결 방식을 연결합니다."},{"type":"features","heading":"이야기에 꼭 넣을 세 가지","items":[{"title":"문제의 장면","body":"고객이 실제로 불편을 느끼는 순간을 구체적으로 보여 줍니다."},{"title":"우리의 관점","body":"다른 선택지 대신 이 방법을 고른 이유를 설명합니다."},{"title":"지금의 약속","body":"고객에게 어떤 변화를 만들겠다는지 짧고 선명하게 적습니다."}]},{"type":"text","heading":"고객이 자기 이야기처럼 읽게 하세요","body":"브랜드 스토리는 멋진 문장보다 정확한 공감에서 힘을 얻습니다. 고객 인터뷰에서 나온 표현을 활용하면 소개글과 콘텐츠의 설득력이 높아집니다."}]$$::jsonb, '브랜드 스토리 작성법: 고객이 공감하는 브랜드 소개 만들기', '브랜드의 시작, 문제의식, 약속을 고객의 언어로 정리하는 실전 작성법입니다.', '브랜드 스토리 작성법', array['브랜드 소개','브랜드 메시지'], now() - interval '3 days'),
  ('customer-interview-questions', '고객 인터뷰 질문 10가지: 답보다 맥락을 얻는 법', '제품을 만들기 전 고객의 실제 행동과 문제를 이해하는 인터뷰 방법을 정리했습니다.', $$[{"type":"text","heading":"좋은 인터뷰는 정답을 유도하지 않습니다","body":"‘이 기능이 있으면 쓰시겠어요?’라는 질문은 친절한 대답만 남기기 쉽습니다. 고객 인터뷰에서는 의견보다 최근 행동을 물어야 합니다. 언제, 어떤 이유로, 어떤 방법을 선택했는지 들어야 진짜 문제의 맥락이 보입니다."},{"type":"features","heading":"반드시 물어볼 질문","items":[{"title":"최근 경험","body":"이 문제를 마지막으로 겪은 날과 상황을 묻습니다."},{"title":"현재의 대안","body":"지금은 무엇으로 해결하는지, 왜 불편한지 확인합니다."},{"title":"결정의 기준","body":"시간, 비용, 신뢰 중 무엇이 선택에 영향을 줬는지 찾습니다."}]},{"type":"text","heading":"인터뷰 뒤에는 문장을 정리하세요","body":"인터뷰가 끝나면 인상적인 말보다 반복해서 등장한 행동과 표현을 모으세요. 그 문장이 제품의 우선순위와 랜딩페이지 카피의 출발점이 됩니다."}]$$::jsonb, '고객 인터뷰 질문 10가지: 스타트업이 꼭 물어봐야 할 것', '고객의 실제 문제와 행동을 파악하기 위한 스타트업 고객 인터뷰 질문과 정리법입니다.', '고객 인터뷰 질문', array['사용자 인터뷰','고객 조사'], now() - interval '4 days'),
  ('landing-page-conversion', '랜딩페이지 전환율 높이는 법: 첫 화면부터 다시 점검하기', '방문자가 제품을 이해하고 다음 행동을 선택하게 만드는 랜딩페이지 구성법입니다.', $$[{"type":"text","heading":"첫 화면은 제품 설명서가 아닙니다","body":"랜딩페이지 첫 화면의 역할은 모든 기능을 설명하는 것이 아니라 방문자가 ‘나를 위한 것’이라고 알아보게 하는 것입니다. 고객의 문제, 약속하는 변화, 다음 행동을 한 화면에서 빠르게 이해할 수 있어야 합니다."},{"type":"features","heading":"전환을 만드는 구성","items":[{"title":"명확한 한 줄","body":"누구를 위해 어떤 결과를 만드는지 제목에서 먼저 말합니다."},{"title":"증거","body":"사용 장면, 후기, 수치처럼 약속을 뒷받침하는 근거를 둡니다."},{"title":"하나의 CTA","body":"무료 체험, 상담 신청처럼 지금 해야 할 행동을 하나로 집중합니다."}]},{"type":"text","heading":"추측 대신 관찰로 개선하세요","body":"전환율을 높이는 가장 빠른 방법은 고객이 어디에서 멈추는지 보는 것입니다. 문의 내용과 세션 기록을 함께 보며 한 번에 한 요소씩 바꾸세요."}]$$::jsonb, '랜딩페이지 전환율 높이는 법: 스타트업 첫 화면 점검', '고객이 제품을 이해하고 전환하도록 만드는 랜딩페이지 제목, 증거, CTA 구성법입니다.', '랜딩페이지 전환율', array['랜딩페이지 제작','전환율 개선'], now() - interval '5 days'),
  ('seo-keyword-research', 'SEO 키워드 찾는 법: 고객이 검색하는 문장부터 시작하기', '검색량만 보지 않고 전환 가능성이 높은 SEO 키워드를 고르는 방법입니다.', $$[{"type":"text","heading":"좋은 키워드는 고객의 질문에 가깝습니다","body":"검색량이 큰 단어가 항상 좋은 키워드는 아닙니다. 제품을 찾는 사람이 어떤 상황에서 무엇을 해결하려 검색하는지 살펴야 합니다. 고객 문의, 상담 기록, 커뮤니티 질문은 가장 현실적인 키워드 출처입니다."},{"type":"features","heading":"키워드 우선순위 정하기","items":[{"title":"검색 의도","body":"정보를 찾는지, 비교하는지, 바로 선택하려는지 구분합니다."},{"title":"제품 연결성","body":"글을 읽은 뒤 자연스럽게 제품이나 다음 콘텐츠로 이어질 수 있는지 봅니다."},{"title":"구체성","body":"넓은 단어보다 문제와 상황이 담긴 긴 검색어부터 공략합니다."}]},{"type":"text","heading":"한 글에 한 질문을 답하세요","body":"SEO 글은 여러 주제를 얕게 모으기보다 한 가지 질문에 가장 유용한 답을 주는 편이 좋습니다. 제목, 소제목, 본문을 같은 검색 의도에 맞추세요."}]$$::jsonb, 'SEO 키워드 찾는 법: 고객 검색 의도로 키워드 선정하기', '검색량보다 고객의 문제와 전환 가능성을 기준으로 SEO 키워드를 찾고 우선순위를 정하는 법입니다.', 'SEO 키워드 찾는 법', array['키워드 리서치','콘텐츠 SEO'], now() - interval '6 days'),
  ('mvp-validation', 'MVP 검증 방법: 만들기 전에 확인해야 할 3가지', '최소 기능 제품을 만들기 전 문제, 고객, 행동을 검증하는 방법입니다.', $$[{"type":"text","heading":"MVP는 작은 제품이 아니라 작은 가설입니다","body":"MVP를 기능이 적은 완성품으로 생각하면 검증까지 오래 걸립니다. 먼저 확인할 것은 고객이 정말 문제를 느끼는지, 제안한 해결 방식에 반응하는지, 다음 행동을 할 의사가 있는지입니다."},{"type":"features","heading":"검증할 세 가지","items":[{"title":"문제의 빈도","body":"그 문제가 얼마나 자주, 얼마나 불편하게 발생하는지 확인합니다."},{"title":"대안의 한계","body":"고객이 현재 쓰는 방법에서 무엇을 포기하고 있는지 찾습니다."},{"title":"행동의 신호","body":"칭찬보다 신청, 예약, 자료 공유처럼 실제 행동을 봅니다."}]},{"type":"text","heading":"검증은 빠른 포기가 아니라 빠른 학습입니다","body":"가설이 틀렸다는 결과도 다음 선택을 선명하게 만듭니다. 한 번의 실험에 모든 답을 기대하지 말고, 다음 질문을 만들 수 있을 만큼만 작게 테스트하세요."}]$$::jsonb, 'MVP 검증 방법: 스타트업이 제품 만들기 전 확인할 3가지', 'MVP를 만들기 전 고객 문제, 기존 대안, 실제 행동을 검증하는 방법을 소개합니다.', 'MVP 검증', array['스타트업 아이템 검증','최소 기능 제품'], now() - interval '7 days'),
  ('customer-persona-guide', '고객 페르소나 만들기: 타깃 고객을 선명하게 정하는 법', '데이터와 인터뷰를 바탕으로 실제 의사결정에 쓰이는 고객 페르소나 작성법입니다.', $$[{"type":"text","heading":"페르소나는 상상 속 인물이 아닙니다","body":"나이와 직업만 적은 페르소나는 마케팅 의사결정에 도움이 되지 않습니다. 좋은 페르소나는 어떤 상황에서 문제를 느끼고, 무엇을 비교하며, 어떤 기준으로 선택하는지 보여 줍니다."},{"type":"features","heading":"페르소나에 담을 정보","items":[{"title":"문제가 생기는 순간","body":"하루의 어느 장면에서 불편이 시작되는지 적습니다."},{"title":"기존 해결 방법","body":"현재 사용하는 도구와 그 선택의 이유를 확인합니다."},{"title":"구매를 망설이는 이유","body":"비용, 신뢰, 전환 부담 중 무엇이 장벽인지 기록합니다."}]},{"type":"text","heading":"한 명을 정하면 메시지가 쉬워집니다","body":"모든 고객을 동시에 설득하려 하면 문장이 흐려집니다. 가장 먼저 도울 고객을 정하고, 그 사람의 언어로 제품과 콘텐츠를 설명하세요."}]$$::jsonb, '고객 페르소나 만들기: 타깃 고객을 정하는 실전 가이드', '실제 고객 인터뷰와 행동 데이터를 바탕으로 마케팅에 쓰이는 고객 페르소나를 만드는 방법입니다.', '고객 페르소나', array['타깃 고객','마케팅 페르소나'], now() - interval '8 days'),
  ('product-positioning', '제품 포지셔닝 전략: 고객의 머릿속에 한 자리를 만드는 법', '경쟁 제품과 다른 이유를 명확하게 전달하는 제품 포지셔닝의 기본을 소개합니다.', $$[{"type":"text","heading":"포지셔닝은 경쟁사를 나열하는 일이 아닙니다","body":"제품 포지셔닝은 고객이 비슷한 선택지 사이에서 우리를 언제 떠올릴지를 정하는 일입니다. 기능이 많다는 말보다 특정 상황에서 가장 적합한 이유를 만드는 것이 중요합니다."},{"type":"features","heading":"포지셔닝을 정하는 질문","items":[{"title":"누구에게 필요한가","body":"가장 강한 문제를 가진 고객을 먼저 정의합니다."},{"title":"언제 선택되는가","body":"고객이 기존 도구 대신 바꾸고 싶어지는 순간을 찾습니다."},{"title":"무엇을 포기하지 않는가","body":"고객이 중요하게 여기는 기준을 지키면서 어떤 이점을 더하는지 말합니다."}]},{"type":"text","heading":"모든 접점에서 같은 약속을 반복하세요","body":"포지셔닝은 슬로건 한 줄로 끝나지 않습니다. 홈페이지, 데모, 고객 지원, 콘텐츠에서 같은 약속이 반복될 때 고객의 기억에 남습니다."}]$$::jsonb, '제품 포지셔닝 전략: 고객에게 선택받는 이유 만들기', '경쟁 제품 사이에서 고객이 우리 제품을 떠올리게 만드는 제품 포지셔닝 전략과 질문을 정리했습니다.', '제품 포지셔닝', array['브랜드 포지셔닝','제품 차별화'], now() - interval '9 days'),
  ('early-adopter-acquisition', '초기 사용자 확보 방법: 첫 고객을 만나는 가장 현실적인 경로', '초기 스타트업이 광고 없이 첫 사용자를 찾고 관계를 만드는 방법입니다.', $$[{"type":"text","heading":"초기 사용자는 넓게 찾지 않습니다","body":"처음에는 시장 전체보다 문제가 가장 선명한 작은 집단을 찾아야 합니다. 이미 같은 불편을 이야기하는 커뮤니티, 업계 모임, 지인의 소개가 좋은 출발점이 됩니다."},{"type":"features","heading":"첫 고객을 만나는 경로","items":[{"title":"문제가 있는 곳에 참여하기","body":"홍보 글부터 올리기보다 대화를 읽고 도움 되는 답을 먼저 남깁니다."},{"title":"개인적인 초대 보내기","body":"왜 이 사람에게 연락했는지와 무엇을 함께 확인하고 싶은지 구체적으로 말합니다."},{"title":"피드백을 다시 보여주기","body":"받은 의견이 제품에 어떻게 반영됐는지 알려 관계를 이어갑니다."}]},{"type":"text","heading":"첫 사용자는 다음 사용자를 데려옵니다","body":"초기 고객이 만족하면 소개와 후기, 더 정확한 언어가 따라옵니다. 숫자를 급하게 늘리기보다 한 사람의 첫 경험을 끝까지 좋게 만드는 데 집중하세요."}]$$::jsonb, '초기 사용자 확보 방법: 스타트업 첫 고객 찾기', '광고비 없이 초기 스타트업이 첫 고객을 찾고 피드백 관계를 만드는 현실적인 방법입니다.', '초기 사용자 확보', array['첫 고객 찾기','초기 스타트업'], now() - interval '10 days'),
  ('startup-pr-checklist', '스타트업 PR 전략: 보도자료 전에 준비해야 할 것들', '기사 배포보다 중요한 이야기의 각도와 자료 준비를 정리한 스타트업 PR 가이드입니다.', $$[{"type":"text","heading":"PR은 알림이 아니라 맥락을 만드는 일입니다","body":"투자 유치나 기능 출시만으로는 기사 가치가 생기기 어렵습니다. 왜 지금 이 변화가 필요한지, 어떤 고객의 문제를 새롭게 풀었는지라는 맥락이 있어야 외부의 관심을 얻을 수 있습니다."},{"type":"features","heading":"PR 자료에 담을 내용","items":[{"title":"한 문장의 뉴스","body":"이번 소식이 누구에게 왜 중요한지 제목으로 설명합니다."},{"title":"검증 가능한 근거","body":"고객 사례, 사용 데이터, 팀의 경험처럼 사실을 뒷받침할 자료를 준비합니다."},{"title":"연락 가능한 사람","body":"추가 질문에 빠르게 답할 담당자와 이미지, 링크를 함께 둡니다."}]},{"type":"text","heading":"관계는 기사 한 건보다 오래갑니다","body":"기자와 독자에게 도움이 되는 관점을 꾸준히 나누면 다음 소식도 더 잘 이해됩니다. PR은 단발성 노출보다 신뢰할 수 있는 이야기의 축적입니다."}]$$::jsonb, '스타트업 PR 전략: 보도자료 전 준비해야 할 체크리스트', '스타트업이 보도자료와 PR을 준비할 때 필요한 뉴스 각도, 근거 자료, 미디어 관계의 기본을 안내합니다.', '스타트업 PR', array['보도자료 작성','스타트업 브랜딩'], now() - interval '11 days'),
  ('founder-personal-branding', '창업가 퍼스널 브랜딩: 제품을 앞세우면서 신뢰를 만드는 법', '창업가가 과장 없이 자신의 관점과 제품의 신뢰를 쌓는 콘텐츠 방법입니다.', $$[{"type":"text","heading":"창업가의 이야기는 제품의 맥락이 됩니다","body":"사람들은 제품의 기능만큼 누가 어떤 문제를 오래 고민했는지 궁금해합니다. 퍼스널 브랜딩은 자신을 과시하는 일이 아니라, 팀이 왜 이 문제를 풀 자격이 있는지 보여 주는 기록입니다."},{"type":"features","heading":"꾸준히 나눌 수 있는 소재","items":[{"title":"고객에게 배운 것","body":"인터뷰와 지원 과정에서 발견한 문제를 익명으로 정리합니다."},{"title":"제품의 선택","body":"무엇을 만들지 않았는지와 그 이유를 솔직하게 설명합니다."},{"title":"일하는 방식","body":"팀이 실험하고 판단하는 과정을 공유해 관점을 보여 줍니다."}]},{"type":"text","heading":"진정성은 구체성에서 나옵니다","body":"성공담만 반복하기보다 고민과 기준을 구체적으로 남기세요. 창업가의 꾸준한 기록은 제품을 처음 만나는 사람에게 가장 신뢰도 높은 소개가 됩니다."}]$$::jsonb, '창업가 퍼스널 브랜딩: 신뢰를 만드는 콘텐츠 전략', '창업가가 고객의 신뢰를 얻고 제품의 맥락을 전달하는 퍼스널 브랜딩 콘텐츠 방법입니다.', '창업가 퍼스널 브랜딩', array['대표 브랜딩','창업가 콘텐츠'], now() - interval '12 days'),
  ('startup-content-marketing', '스타트업 콘텐츠 마케팅: 제품 홍보처럼 보이지 않는 콘텐츠 만들기', '고객에게 먼저 도움이 되면서 제품과 자연스럽게 연결되는 콘텐츠 전략입니다.', $$[{"type":"text","heading":"콘텐츠는 제품 설명의 다른 이름이 아닙니다","body":"모든 글이 제품 소개로 끝나면 독자는 금방 떠납니다. 스타트업 콘텐츠는 고객이 문제를 이해하고 더 나은 결정을 하도록 돕는 정보에서 시작해야 합니다."},{"type":"features","heading":"계속 읽히는 콘텐츠 주제","items":[{"title":"고객의 질문","body":"상담과 인터뷰에서 반복된 질문을 하나의 글로 답합니다."},{"title":"선택의 기준","body":"도구나 방법을 비교할 때 봐야 할 기준을 정리합니다."},{"title":"팀의 배움","body":"제품을 만들며 검증한 인사이트를 재현 가능한 형태로 나눕니다."}]},{"type":"text","heading":"도움이 된 뒤에 제품을 소개하세요","body":"글의 결론에서 제품을 억지로 밀기보다, 더 알아볼 사람을 위한 다음 경로를 제안하세요. 신뢰가 쌓인 콘텐츠는 가장 오래 가는 유입 채널이 됩니다."}]$$::jsonb, '스타트업 콘텐츠 마케팅: 고객에게 읽히는 글 만드는 법', '제품 홍보로 끝나지 않고 고객에게 먼저 도움이 되는 스타트업 콘텐츠 마케팅 전략입니다.', '스타트업 콘텐츠 마케팅', array['콘텐츠 전략','B2B 콘텐츠 마케팅'], now() - interval '13 days'),
  ('customer-review-collection', '고객 후기 받는 법: 신뢰를 만드는 후기 요청 가이드', '부담스럽지 않게 고객 경험을 듣고 마케팅에 활용하는 방법을 정리했습니다.', $$[{"type":"text","heading":"좋은 후기는 질문에서 시작합니다","body":"‘후기를 남겨 주세요’라는 요청은 막막합니다. 고객이 어떤 문제를 겪었고, 제품을 쓰며 무엇이 달라졌는지 묻는 구체적인 질문을 건네면 더 진솔한 이야기를 얻을 수 있습니다."},{"type":"features","heading":"후기를 요청하기 좋은 순간","items":[{"title":"첫 성과 직후","body":"고객이 제품의 가치를 체감한 순간에 짧게 요청합니다."},{"title":"지원이 해결된 뒤","body":"문제가 해결된 경험은 신뢰를 보여 주는 좋은 사례가 됩니다."},{"title":"정기 사용 시점","body":"일상에 자리 잡은 이유를 물으면 재구매와 추천의 단서를 얻습니다."}]},{"type":"text","heading":"후기는 고객의 언어를 배우는 자료입니다","body":"후기를 홈페이지에 붙이는 데서 끝내지 마세요. 고객이 쓰는 표현을 랜딩페이지와 광고, 세일즈 자료에 반영하면 메시지가 더 자연스러워집니다."}]$$::jsonb, '고객 후기 받는 법: 신뢰를 만드는 후기 요청 방법', '고객에게 부담 없이 후기를 요청하고 마케팅 메시지와 신뢰 자산으로 활용하는 방법입니다.', '고객 후기 받는 법', array['사용자 후기','고객 리뷰'], now() - interval '14 days'),
  ('community-marketing', '커뮤니티 마케팅 시작하기: 고객이 모인 곳에서 신뢰 쌓는 법', '커뮤니티를 광고판이 아닌 고객과 배우는 장소로 활용하는 방법입니다.', $$[{"type":"text","heading":"커뮤니티에서는 먼저 맥락을 읽어야 합니다","body":"고객이 모인 커뮤니티는 빠른 홍보 채널처럼 보이지만, 일방적인 링크는 신뢰를 잃기 쉽습니다. 구성원이 어떤 질문을 반복하고 어떤 표현을 쓰는지 충분히 이해한 뒤 참여해야 합니다."},{"type":"features","heading":"신뢰를 만드는 참여 방식","items":[{"title":"질문에 답하기","body":"제품 링크 대신 경험과 정보를 나누며 문제 해결에 기여합니다."},{"title":"과정을 공개하기","body":"무엇을 배우고 바꾸는지 솔직하게 공유해 대화를 이어갑니다."},{"title":"피드백을 요청하기","body":"누구에게 어떤 부분을 검증받고 싶은지 구체적으로 말합니다."}]},{"type":"text","heading":"관계가 쌓이면 전환은 따라옵니다","body":"커뮤니티 마케팅의 성과는 즉시 구매로만 보이지 않습니다. 고객의 언어, 초기 사용자, 소개가 차곡차곡 쌓이며 더 강한 브랜드 기반이 됩니다."}]$$::jsonb, '커뮤니티 마케팅 시작하기: 고객 신뢰를 쌓는 방법', '고객이 모인 커뮤니티에서 광고 대신 신뢰를 쌓고 초기 사용자를 만나는 방법을 안내합니다.', '커뮤니티 마케팅', array['초기 사용자','브랜드 커뮤니티'], now() - interval '15 days'),
  ('product-demo-guide', '제품 데모 잘하는 법: 기능 설명을 고객의 결과로 바꾸기', '짧은 제품 데모에서 고객이 가치를 이해하도록 만드는 구성과 대화법입니다.', $$[{"type":"text","heading":"데모는 클릭 순서가 아니라 문제의 흐름입니다","body":"기능을 하나씩 보여 주는 데모는 고객에게 기억되기 어렵습니다. 고객이 겪는 문제에서 시작해 제품으로 어떤 행동이 줄고 결과가 달라지는지 하나의 흐름으로 보여 주세요."},{"type":"features","heading":"좋은 데모의 순서","items":[{"title":"상황 제시","body":"고객이 익숙한 업무나 일상의 장면으로 시작합니다."},{"title":"핵심 행동","body":"가장 큰 변화를 만드는 기능 하나를 직접 보여 줍니다."},{"title":"결과 확인","body":"시간, 오류, 의사결정처럼 고객이 얻는 결과를 다시 연결합니다."}]},{"type":"text","heading":"고객의 질문이 데모를 완성합니다","body":"예정한 설명을 모두 끝내는 것보다 고객이 궁금해한 지점에서 멈추는 편이 좋습니다. 질문을 기록하면 다음 데모와 제품 메시지가 함께 개선됩니다."}]$$::jsonb, '제품 데모 잘하는 법: 고객이 가치를 이해하는 데모 구성', '기능 나열이 아닌 고객의 문제와 결과 중심으로 제품 데모를 구성하는 방법을 소개합니다.', '제품 데모', array['SaaS 데모','제품 소개'], now() - interval '16 days'),
  ('b2b-lead-generation', 'B2B 리드 확보 방법: 관심 있는 고객과 대화를 시작하는 법', '무작정 연락하기보다 B2B 잠재 고객의 관심을 만들고 대화로 연결하는 방법입니다.', $$[{"type":"text","heading":"리드는 명단이 아니라 대화의 가능성입니다","body":"B2B 리드 확보에서 중요한 것은 많은 회사 이름을 모으는 일이 아닙니다. 우리 제품이 해결하는 문제가 실제로 있고, 그 문제를 담당하는 사람에게 적절한 맥락으로 연락하는 일이 먼저입니다."},{"type":"features","heading":"대화를 만드는 세 단계","items":[{"title":"적합한 계정 정의","body":"업종, 팀 규모, 현재 사용하는 방식으로 우선순위를 좁힙니다."},{"title":"문제의 신호 찾기","body":"채용, 신규 서비스, 고객 문의처럼 변화가 생긴 시점을 살핍니다."},{"title":"도움이 되는 제안","body":"제품 소개보다 상대가 바로 활용할 수 있는 관찰이나 자료를 먼저 보냅니다."}]},{"type":"text","heading":"다음 행동을 쉽게 제안하세요","body":"긴 미팅 요청보다 짧은 질문이나 자료 확인처럼 부담이 적은 다음 단계를 제안하면 대화가 시작될 가능성이 높아집니다."}]$$::jsonb, 'B2B 리드 확보 방법: 잠재 고객과 대화를 시작하는 전략', 'B2B 스타트업이 적합한 잠재 고객을 찾고 신뢰 있는 첫 대화를 만드는 방법입니다.', 'B2B 리드 확보', array['B2B 마케팅','잠재 고객 발굴'], now() - interval '17 days'),
  ('startup-growth-metrics', '스타트업 성장 지표: 처음부터 봐야 할 핵심 지표 5가지', '허상 지표에 흔들리지 않고 제품과 고객의 성장을 판단하는 기준을 소개합니다.', $$[{"type":"text","heading":"숫자는 많을수록 좋은 것이 아닙니다","body":"초기 스타트업은 방문자 수와 팔로워 수처럼 보기 좋은 숫자에 집중하기 쉽습니다. 하지만 성장 판단에는 고객이 제품의 가치를 경험했는지 보여 주는 행동 지표가 더 중요합니다."},{"type":"features","heading":"처음부터 볼 지표","items":[{"title":"활성 사용","body":"고객이 핵심 행동을 실제로 반복하는지 봅니다."},{"title":"재방문과 유지","body":"한 번의 호기심이 습관이나 업무 흐름으로 이어지는지 확인합니다."},{"title":"전환 경로","body":"어떤 채널과 메시지가 적합한 고객을 데려오는지 기록합니다."}]},{"type":"text","heading":"지표는 질문과 함께 봐야 합니다","body":"수치가 올랐거나 내려갔다는 사실만으로는 부족합니다. 어떤 고객이 어떤 이유로 움직였는지 인터뷰와 함께 보면 다음 실험의 방향이 보입니다."}]$$::jsonb, '스타트업 성장 지표: 초기 팀이 봐야 할 핵심 KPI', '초기 스타트업이 방문자 수보다 먼저 확인해야 할 활성 사용, 유지, 전환 중심의 성장 지표를 설명합니다.', '스타트업 성장 지표', array['스타트업 KPI','제품 성장'], now() - interval '18 days'),
  ('startup-pivot-decision', '스타트업 피봇 기준: 방향을 바꿔야 할 때 확인할 신호', '성급한 방향 전환과 필요한 피봇을 구분하는 질문과 검증 방법입니다.', $$[{"type":"text","heading":"피봇은 실패의 반대말이 아닙니다","body":"피봇은 처음의 가설을 버리는 일이 아니라, 고객에게서 배운 사실에 맞춰 더 나은 방향을 선택하는 일입니다. 단기 성과가 낮다는 이유만으로 바꾸기보다 반복되는 신호를 먼저 확인해야 합니다."},{"type":"features","heading":"방향을 점검할 신호","items":[{"title":"문제의 강도","body":"고객이 불편을 인정하지만 해결을 위해 행동하지 않는지 봅니다."},{"title":"반복되는 요청","body":"여러 고객이 같은 다른 용도를 요구하는지 확인합니다."},{"title":"유지의 이유","body":"남아 있는 고객이 어떤 가치 때문에 계속 쓰는지 찾습니다."}]},{"type":"text","heading":"한 번에 하나의 가설만 바꾸세요","body":"고객군, 문제, 해결책을 모두 동시에 바꾸면 무엇을 배웠는지 알 수 없습니다. 가장 강한 신호를 기준으로 한 가지를 바꾸고 다시 검증하세요."}]$$::jsonb, '스타트업 피봇 기준: 방향을 바꿔야 할 때 확인할 신호', '초기 스타트업이 고객 신호를 바탕으로 필요한 피봇과 성급한 방향 전환을 구분하는 방법입니다.', '스타트업 피봇', array['사업 방향 전환','스타트업 전략'], now() - interval '19 days'),
  ('startup-funding-preparation', '투자 유치 준비: 스타트업이 먼저 정리해야 할 이야기', '투자 자료를 만들기 전 팀, 시장, 고객의 진전을 한 이야기로 정리하는 방법입니다.', $$[{"type":"text","heading":"투자 자료는 숫자의 모음이 아닙니다","body":"투자 유치 준비에서 가장 먼저 필요한 것은 왜 지금 이 팀이 이 문제를 풀어야 하는지 설명하는 이야기입니다. 시장의 기회, 고객의 문제, 지금까지의 검증이 한 흐름으로 이어져야 합니다."},{"type":"features","heading":"먼저 정리할 자료","items":[{"title":"고객 문제","body":"누가 어떤 불편을 겪고 있으며 왜 기존 대안이 부족한지 적습니다."},{"title":"검증의 증거","body":"사용자 인터뷰, 매출, 재방문, 파일럿처럼 실제 진전을 모읍니다."},{"title":"다음 이정표","body":"투자로 무엇을 검증하고 어떤 지표를 만들 것인지 구체적으로 정합니다."}]},{"type":"text","heading":"완벽한 답보다 선명한 학습이 중요합니다","body":"초기 팀이 모든 것을 증명할 수는 없습니다. 대신 무엇을 알고 무엇을 검증 중이며, 다음 자원을 어디에 쓸지 명확하게 보여 주세요."}]$$::jsonb, '투자 유치 준비: 스타트업이 먼저 정리해야 할 핵심 이야기', '투자 자료 작성 전 고객 문제, 검증 증거, 다음 이정표를 한 이야기로 정리하는 방법입니다.', '투자 유치 준비', array['스타트업 투자','IR 자료'], now() - interval '20 days')
)
insert into public.features (
  slug, title, kind, excerpt, body, status, published_at,
  seo_title, seo_description, primary_keyword, secondary_keywords, is_indexable, updated_at
)
select
  slug, title, 'brand-story', excerpt, body, 'published', published_at,
  seo_title, seo_description, primary_keyword, secondary_keywords, true, timezone('utc', now())
from posts
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  body = excluded.body,
  status = 'published',
  published_at = excluded.published_at,
  seo_title = excluded.seo_title,
  seo_description = excluded.seo_description,
  primary_keyword = excluded.primary_keyword,
  secondary_keywords = excluded.secondary_keywords,
  is_indexable = true,
  updated_at = excluded.updated_at;
